// getOrCreateRequestContext creates a new certificate request for a given context,
// if there is no active CSR request in progress, or returns an existing one.
// if the new context has been created, cancel function is returned as a
// second argument. Caller should call this function to signal that CSR has been
// completed or failed.
func (f *Forwarder) getOrCreateRequestContext(key string) (context.Context, context.CancelFunc) {
	f.Lock()
	defer f.Unlock()
	if f.activeRequests == nil {
		f.activeRequests = make(map[string]context.Context)
	}
	ctx, ok := f.activeRequests[key]
	if ok {
		return ctx, nil
	}
	ctx, cancel := context.WithCancel(f.ctx)
	f.activeRequests[key] = ctx
	return ctx, func() {
		cancel()
		f.Lock()
		defer f.Unlock()
		delete(f.activeRequests, key)
	}
}

type cachedKubeCredentials struct {
	tlsConfig *tls.Config
	notAfter  time.Time
}

func (f *Forwarder) getOrCreateCredentials(ctx authContext) (*tls.Config, error) {
	key := ctx.key()
	if credentials := f.getCachedCredentials(key); credentials != nil {
		return credentials, nil
	}

	requestContext, finish := f.getOrCreateRequestContext(key)
	if finish != nil {
		defer finish()

		f.log.Debugf("Requesting Kubernetes credentials for %v.", ctx)
		tlsConfig, err := f.requestCertificate(ctx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		notAfter, err := kubeCertificateExpiry(tlsConfig)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if notAfter.Before(f.Clock.Now().Add(time.Minute)) {
			return nil, trace.BadParameter("Kubernetes certificate expires in less than one minute")
		}
		cacheTTL := ctx.sessionTTL
		if cacheTTL <= 0 {
			cacheTTL = time.Minute
		}
		if err := f.credentials.Set(key, cachedKubeCredentials{
			tlsConfig: tlsConfig,
			notAfter:  notAfter,
		}, cacheTTL); err != nil {
			return nil, trace.Wrap(err)
		}
		return tlsConfig, nil
	}

	// Another request is processing a CSR for this authenticated context.
	f.log.Debugf("Waiting for Kubernetes credentials for %v.", ctx)
	select {

	sess := &clusterSession{
		parent:      f,
		authContext: ctx,
	}
	var err error
	sess.tlsConfig, err = f.getOrCreateCredentials(ctx)
	if err != nil {
		f.log.Warningf("Failed to get certificate for %v: %v.", ctx, err)
		return nil, trace.AccessDenied("access denied: failed to authenticate with auth server")
	}
	// remote clusters use special hardcoded URL,
	// and use a special dialer
	sess.authContext.teleportCluster.targetAddr = reversetunnel.LocalKubernetes
	transport := f.newTransport(sess.Dial, sess.tlsConfig)
	sess.transport = transport

	sess.forwarder, err = forward.New(
		forward.FlushInterval(100*time.Millisecond),
		forward.RoundTripper(transport),
		forward.WebsocketDial(sess.Dial),
		forward.Logger(f.log),
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return sess, nil
}

